        long[][] m;
        int r, c;

        Matrix(int r, int c) {
            this.r = r;
            this.c = c;
            m = new long[r][c];
        }
    }

    static Matrix mul(Matrix a, Matrix b, long mod) {
        Matrix c = new Matrix(a.r, b.c);
        for (int i = 0; i < a.r; i++) {
            for (int k = 0; k < a.c; k++) {
                for (int j = 0; j < b.c; j++) {
